package com.notireader.app.data

import androidx.lifecycle.LiveData
import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query

@Dao
interface MessageDao {
    @Insert
    suspend fun insertMessage(message: MessageEntity)

    @Query("SELECT * FROM messages ORDER BY timestamp DESC")
    fun getAllMessages(): LiveData<List<MessageEntity>>

    @Query("UPDATE messages SET isDeleted = 1 WHERE id = :id")
    suspend fun markAsDeleted(id: Int)
}

package com.notireader.app.data

import androidx.lifecycle.LiveData
import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query

@Dao
interface MessageDao {
    @Insert
    suspend fun insertMessage(message: MessageEntity)

    @Query("SELECT * FROM messages ORDER BY timestamp DESC")
    fun getAllMessages(): LiveData<List<MessageEntity>>

    @Query("UPDATE messages SET isDeleted = 1 WHERE id = :id")
    suspend fun markAsDeleted(id: Int)

    @Query("UPDATE messages SET isDeleted = 1 WHERE sender = :sender AND message = :message AND timestamp = :timestamp")
    suspend fun markAsDeletedByDetails(sender: String, message: String, timestamp: Long)
}

package com.notireader.app.domain
import androidx.lifecycle.LiveData
interface NotiRepository { fun getAllMessages(): LiveData<List<MessageModel>> suspend fun insertMessage(message: MessageModel) suspend fun markMessageAsDeleted(id: Int) suspend fun onWhatsAppNotificationReceived(message: MessageModel) }

package com.notireader.app.domain
import androidx.lifecycle.LiveData
interface NotiRepository { fun getAllMessages(): LiveData<List<MessageModel>> suspend fun insertMessage(message: MessageModel) suspend fun markMessageAsDeleted(id: Int) suspend fun onWhatsAppNotificationReceived(message: MessageModel) suspend fun markMessageAsDeletedByDetails(sender: String, message: String, timestamp: Long) }

package com.notireader.app.domain

import android.service.notification.NotificationListenerService
import android.service.notification.StatusBarNotification
import dagger.hilt.android.AndroidEntryPoint
import javax.inject.Inject
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

@AndroidEntryPoint
class WhatsAppNotificationListener : NotificationListenerService() {
    @Inject
    lateinit var notiRepository: NotiRepository

    var title: String? = ""
    var message: CharSequence? = ""
    var timeStamp: Long = 0
    var isDeleted: Boolean = false

    override fun onNotificationPosted(sbn: StatusBarNotification?) {
        super.onNotificationPosted(sbn)
        if (sbn?.packageName == "com.whatsapp") {
            val title = sbn.notification.extras.getString("android.title") ?: ""
            val message = sbn.notification.extras.getCharSequence("android.text")?.toString() ?: ""
            val timeStamp = sbn.postTime
            val messageModel = MessageModel(
                sender = title,
                message = message,
                timestamp = timeStamp,
                isDeleted = false
            )
            CoroutineScope(Dispatchers.IO).launch {
                notiRepository.onWhatsAppNotificationReceived(messageModel)
            }
        }
    }

    override fun onNotificationRemoved(sbn: StatusBarNotification?, rankingMap: RankingMap?, reason: Int) {
        super.onNotificationRemoved(sbn, rankingMap, reason)
        if (sbn?.packageName == "com.whatsapp") {
            if(reason == REASON_APP_CANCEL) {
                isDeleted = true
            }
        }
    }
}

package com.notireader.app.domain

import android.service.notification.NotificationListenerService
import android.service.notification.StatusBarNotification
import dagger.hilt.android.AndroidEntryPoint
import javax.inject.Inject
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

@AndroidEntryPoint
class WhatsAppNotificationListener : NotificationListenerService() {
    @Inject
    lateinit var notiRepository: NotiRepository

    var title: String? = ""
    var message: CharSequence? = ""
    var timeStamp: Long = 0
    var isDeleted: Boolean = false

    override fun onNotificationPosted(sbn: StatusBarNotification?) {
        super.onNotificationPosted(sbn)
        if (sbn?.packageName == "com.whatsapp") {
            val title = sbn.notification.extras.getString("android.title") ?: ""
            val message = sbn.notification.extras.getCharSequence("android.text")?.toString() ?: ""
            val timeStamp = sbn.postTime
            val messageModel = MessageModel(
                sender = title,
                message = message,
                timestamp = timeStamp,
                isDeleted = false
            )
            CoroutineScope(Dispatchers.IO).launch {
                notiRepository.onWhatsAppNotificationReceived(messageModel)
            }
        }
    }

    override fun onNotificationRemoved(sbn: StatusBarNotification?, rankingMap: RankingMap?, reason: Int) {
        super.onNotificationRemoved(sbn, rankingMap, reason)
        if (sbn?.packageName == "com.whatsapp") {
            if (reason == REASON_APP_CANCEL) {
                val title = sbn.notification.extras.getString("android.title") ?: ""
                val message = sbn.notification.extras.getCharSequence("android.text")?.toString() ?: ""
                val timeStamp = sbn.postTime
                CoroutineScope(Dispatchers.IO).launch {
                    notiRepository.markMessageAsDeletedByDetails(title, message, timeStamp)
                }
            }
        }
    }
}

package com.notireader.app.presentation.whatsapp_screen_fragment

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.notireader.app.databinding.ItemSenderBinding

class SenderAdapter(
    private val senders: List<String>,
    private val onClick: (String) -> Unit
) : RecyclerView.Adapter<SenderAdapter.SenderViewHolder>() {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): SenderViewHolder {
        val binding = ItemSenderBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return SenderViewHolder(binding)
    }

    override fun onBindViewHolder(holder: SenderViewHolder, position: Int) {
        holder.bind(senders[position])
    }

    override fun getItemCount(): Int = senders.size

    inner class SenderViewHolder(private val binding: ItemSenderBinding) : RecyclerView.ViewHolder(binding.root) {
        fun bind(sender: String) {
            binding.senderName.text = sender
            binding.root.setOnClickListener { onClick(sender) }
        }
    }
}

package com.notireader.app.presentation.whatsapp_screen_fragment

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.notireader.app.R
import com.notireader.app.databinding.ItemSenderBinding
import com.notireader.app.domain.models.MessageModel
import com.notireader.app.util.TimeUtils

class WhatsappAdapter(
    private val onClick: (String) -> Unit,
    private val getUnreadCount: (String, (Int) -> Unit) -> Unit
) : RecyclerView.Adapter<WhatsappAdapter.SenderViewHolder>() {

    private var messages: List<MessageModel> = emptyList()

    fun updateData(newMessages: List<MessageModel>) {
        messages = newMessages
        notifyItemInserted()
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): SenderViewHolder {
        val binding = ItemSenderBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return SenderViewHolder(binding)
    }

    override fun onBindViewHolder(holder: SenderViewHolder, position: Int) {
        holder.bind(messages[position])
    }

    override fun getItemCount(): Int = messages.size

    inner class SenderViewHolder(private val binding: ItemSenderBinding) : RecyclerView.ViewHolder(binding.root) {
        fun bind(message: MessageModel) {
            binding.senderName.text = message.sender
            message.iconRes?.let {
                binding.profilePicture.setImageBitmap(it)
            } ?: binding.profilePicture.setImageResource(R.drawable.ic_user)
            getUnreadCount(message.sender) { count ->
                binding.numberOfUnReads.text = count.toString()
                binding.numberOfUnReads.visibility = if (count > 0) View.VISIBLE else View.GONE
            }
            binding.latestTime.text = TimeUtils.formatTimestamp(message.timestamp, TimeUtils.TIME)
            binding.latestMessage.text = message.message
            binding.root.setOnClickListener { onClick(message.sender) }
        }
    }
}

